import React, { useState, useContext } from "react";
import { MapPin, Save, Edit2, ArrowLeft, Trash2 } from "lucide-react";
import { PlaceContext } from "../contextApi/places.jsx";
import { useDeleteHotelMutation, useUpdateHotelMutation } from "../mutations/hotelMutation.js";

const HotelDetails = () => {
  const { clickedPlace: hotel, setClickedPlaceHandler } = useContext(PlaceContext);
  
  const [data, setData] = useState(hotel || {});
  const [isEditing, setIsEditing] = useState(false);
  const [photoFiles, setPhotoFiles] = useState([]);

  const updateMutation = useUpdateHotelMutation();
  const deleteMutation = useDeleteHotelMutation();

  if (!hotel) return null;

  const handleChange = (e) => {
    setData((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleSave = async () => {
    const formData = new FormData();
    formData.append("data", JSON.stringify(data));
    photoFiles.forEach((f) => formData.append("hotelPhoto", f));

    await updateMutation.mutateAsync({ id: hotel._id, formData });
    setIsEditing(false);
  };

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden font-sans">
      <div className="w-full h-full flex flex-col bg-white">
        <div className="h-16 border-b px-8 flex items-center justify-between">
          <button onClick={() => setClickedPlaceHandler(null)} className="flex items-center text-gray-600">
            <ArrowLeft size={20} className="mr-2" /> Back
          </button>

          <div className="flex gap-3">
            <button
              onClick={() => (isEditing ? handleSave() : setIsEditing(true))}
              className={`flex items-center px-4 py-2 rounded-lg font-bold ${
                isEditing ? "bg-blue-600 text-white" : "bg-gray-100 text-gray-700"
              }`}
            >
              {isEditing ? <><Save size={16} className="mr-2" /> Save</> : <><Edit2 size={16} className="mr-2" /> Edit</>}
            </button>

            <button
              onClick={() => deleteMutation.mutate(hotel._id)}
              className="px-4 py-2 bg-red-600 text-white rounded-lg flex items-center font-bold"
            >
              <Trash2 size={16} className="mr-2" /> Delete
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-6">
          <input
            name="title"
            value={data.title || ""}
            onChange={handleChange}
            disabled={!isEditing}
            className="w-full text-4xl font-extrabold border-b bg-transparent"
          />

          <div className="flex items-center">
            <MapPin size={18} className="mr-2 text-blue-500" />
            <input
              name="location"
              value={data.location || ""}
              onChange={handleChange}
              disabled={!isEditing}
              className="border-b w-full bg-transparent"
            />
          </div>

          <textarea
            name="description"
            value={data.description || ""}
            onChange={handleChange}
            disabled={!isEditing}
            rows={4}
            className="w-full border p-3 rounded-xl bg-gray-50/50"
          />
        </div>
      </div>
    </div>
  );
};

export default HotelDetails;

import React, { useState, useContext, useRef } from "react";
import { MapPin, Star, Plus, X, Upload, Share2, Heart } from "lucide-react";
import { PlaceContext } from "../contextApi/places.jsx";
import HotelDetails from "./HotelDetails.jsx";
import { useHotelsQuery } from "../queries/hotelQueries.js";
import { useAddHotelMutation } from "../mutations/hotelMutation.js";

const HotelCard = ({ hotel }) => {
  const { setClickedPlaceHandler } = useContext(PlaceContext);
  const displayImage = hotel?.photos?.[0]?.url || hotel?.photos?.[0] || "https://via.placeholder.com/400x300?text=No+Image";

  return (
    <div
      className="bg-white rounded-xl shadow-lg overflow-hidden border flex flex-col cursor-pointer group"
      onClick={() => setClickedPlaceHandler(hotel)}
    >
      <div className="relative h-56 bg-gray-900">
        <img src={displayImage} alt={hotel?.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform" />
      </div>
      <div className="p-5 flex flex-col flex-grow">
        <h3 className="font-bold text-xl">{hotel?.title}</h3>
        <p className="text-gray-500 text-sm mt-1">{hotel?.location}</p>
      </div>
    </div>
  );
};

const Hotels = () => {
  const { data, isLoading, isError } = useHotelsQuery();
  const { clickedPlace } = useContext(PlaceContext);
  const addHotelMutation = useAddHotelMutation();

  const [showModal, setShowModal] = useState(false);
  const [form, setForm] = useState({ title: "", location: "", priceRange: "", description: "" });
  const [photoFiles, setPhotoFiles] = useState([]);

  const handleSubmit = async () => {
    const formData = new FormData();
    Object.keys(form).forEach((k) => formData.append(k, form[k]));
    photoFiles.forEach((f) => formData.append("HotelPhotos", f));

    await addHotelMutation.mutateAsync(formData);
    setShowModal(false);
  };

  if (isLoading) return <div className="flex justify-center items-center h-screen font-semibold">Loading Hotels...</div>;
  if (isError) return <div className="flex justify-center items-center h-screen text-red-500">Failed to load hotels.</div>;
  if (clickedPlace) return <HotelDetails />;

  return (
    <div className="min-h-screen bg-gray-50 py-12 px-4">
      <div className="max-w-7xl mx-auto">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {(data?.hotels || []).map((h) => <HotelCard key={h._id} hotel={h} />)}
        </div>
      </div>

      <button onClick={() => setShowModal(true)} className="fixed bottom-8 right-8 bg-blue-600 text-white p-4 rounded-full shadow-lg">
        <Plus size={28} />
      </button>

      {showModal && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center p-4 z-50">
          <div className="bg-white p-6 rounded-2xl max-w-lg w-full space-y-4">
            <h2 className="text-2xl font-bold">Add Property</h2>
            <input placeholder="Hotel Title" className="w-full border p-2 rounded" onChange={(e) => setForm({ ...form, title: e.target.value })} />
            <input placeholder="Location" className="w-full border p-2 rounded" onChange={(e) => setForm({ ...form, location: e.target.value })} />
            <button onClick={handleSubmit} className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold">Submit</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Hotels;

import React, { useState, useRef, useContext, useEffect } from "react";
import {
  Image as ImageIcon, Film, ExternalLink,
  Globe, Compass, Tag, Calendar, Eye
} from "lucide-react";
import { GenericDetailsHeader } from "../components/layout/GenericDetailsHeader.jsx";
import { PlaceContext } from "../contextApi/places.jsx";
import {
  useDeletePlaceMutation,
  useUpdatePlaceMutation,
  useRestorePlaceMutation,
} from "../mutations/placeMutation.js";
import toast from "react-hot-toast";

const getImageUrl = (photo) => {
  if (!photo) return "https://picsum.photos/600/400";
  if (typeof photo === "string") return photo;
  return photo.url || photo.secure_url || "https://picsum.photos/600/400";
};

const PlaceDetails = () => {
  const { clickedPlace, setClickedPlaceHandler } = useContext(PlaceContext);

  const [data, setData] = useState(clickedPlace || {});
  const [isEditing, setIsEditing] = useState(false);
  const [deleteMode, setDeleteMode] = useState(null); // 'soft' | 'hard' | null

  const updatePlaceMutation = useUpdatePlaceMutation();
  const deletePlaceMutation = useDeletePlaceMutation();
  const restorePlaceMutation = useRestorePlaceMutation();

  const [newPhotoFiles, setNewPhotoFiles] = useState([]);
  const [newVideoFile, setNewVideoFile] = useState(null);

  useEffect(() => {
    if (clickedPlace) {
      setData(clickedPlace);
    }
  }, [clickedPlace]);

  if (!clickedPlace) return null;

  const handleChange = (e) => {
    const { name, value } = e.target;
    setData((prev) => ({ ...prev, [name]: value }));
  };

  const handleLocationChange = (e) => {
    const { name, value } = e.target;
    setData((prev) => ({
      ...prev,
      location: {
        ...prev.location,
        [name]: name === "lat" || name === "lng" ? Number(value) || 0 : value,
      },
    }));
  };

  const handleSave = async () => {
    try {
      const formData = new FormData();
      const payload = {
        name: data.name,
        description: data.description,
        category: data.category,
        city: data.city,
        ytVideoLink: data.ytVideoLink,
        likes: Number(data.likes) || 0,
        location: {
          address: data.location?.address || "",
          lat: Number(data.location?.lat) || 0,
          lng: Number(data.location?.lng) || 0,
        },
      };

      formData.append("data", JSON.stringify(payload));
      newPhotoFiles.forEach((file) => formData.append("placePhoto", file));
      if (newVideoFile) formData.append("placeVideo", newVideoFile);

      await updatePlaceMutation.mutateAsync({ id: data._id, formData });
      setIsEditing(false);
      setNewPhotoFiles([]);
      setNewVideoFile(null);
      toast.success("Destination details saved successfully!");
    } catch (_err) {
      toast.error(err?.response?.data?.message || "Failed to update destination");
    }
  };

  const handleSoftDelete = async () => {
    try {
      await deletePlaceMutation.mutateAsync({ id: data._id, hard: false });
      toast.success("Place soft-deleted successfully");
      setDeleteMode(null);
      setClickedPlaceHandler(null);
    } catch (_err) {
      toast.error("Soft deletion failed");
    }
  };

  const handleRestore = async () => {
    try {
      await restorePlaceMutation.mutateAsync(data._id);
      setData((prev) => ({ ...prev, isDeleted: false, deletedAt: null }));
      toast.success("Place restored successfully!");
    } catch (_err) {
      toast.error("Restoration failed");
    }
  };

  const handleHardDelete = async () => {
    try {
      await deletePlaceMutation.mutateAsync({ id: data._id, hard: true });
      toast.error("Place permanently removed from database");
      setDeleteMode(null);
      setClickedPlaceHandler(null);
    } catch (_err) {
      toast.error("Permanent deletion failed");
    }
  };

  const CATEGORY_OPTIONS = [
    "Heritage",
    "Pilgrimage",
    "WildLife",
    "WaterBody",
    "JhansiSmartCity",
    "Treasures",
  ];

  const videoUrl = data.videos?.[0]?.url;

  return (
    <div className="flex h-screen bg-gray-100 overflow-hidden font-sans">
      {/* LEFT FORM & METADATA PANEL */}
      <div className="w-[70%] h-full flex flex-col bg-white border-r shadow-sm z-10">
        
        <GenericDetailsHeader
          onBack={() => setClickedPlaceHandler(null)}
          isDeleted={data.isDeleted}
          isEditing={isEditing}
          isPending={updatePlaceMutation.isPending}
          onRestore={handleRestore}
          onSoftDeleteClick={() => setDeleteMode("soft")}
          onHardDeleteClick={() => setDeleteMode("hard")}
          onSave={handleSave}
          onEditClick={() => setIsEditing(true)}
          backLabel="Back to Destinations"
        />

        {/* CONTENT FIELD CONTAINER */}
        <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-gray-50/50">
          {/* STATUS BADGES & ID */}
          <div className="flex items-center justify-between bg-white p-4 rounded-2xl border shadow-sm">
            <div className="flex items-center gap-3">
              <span className="text-xs font-extrabold text-gray-400 uppercase tracking-widest">
                ID: <span className="font-mono text-gray-700">{data._id}</span>
              </span>
              {data.isDeleted ? (
                <span className="bg-red-100 text-red-700 text-xs px-3 py-1 rounded-full font-bold">
                  Status: Soft Deleted ({new Date(data.deletedAt).toLocaleDateString()})
                </span>
              ) : (
                <span className="bg-green-100 text-green-700 text-xs px-3 py-1 rounded-full font-bold">
                  Status: Active & Public
                </span>
              )}
            </div>

            <div className="flex items-center gap-4 text-xs font-bold text-gray-600">
              <span className="flex items-center gap-1">
                <Heart size={14} className="text-red-500 fill-red-500" />
                Likes:
                <input
                  type="number"
                  name="likes"
                  disabled={!isEditing}
                  value={data.likes || 0}
                  onChange={handleChange}
                  className="w-16 border rounded px-1 text-center ml-1 disabled:bg-transparent"
                />
              </span>
            </div>
          </div>

          {/* BASIC INFORMATION */}
          <div className="bg-white p-6 rounded-2xl border shadow-sm space-y-4">
            <h3 className="text-xs font-black text-blue-600 uppercase tracking-widest flex items-center gap-2">
              <Tag size={16} /> Basic Destination Attributes
            </h3>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
                  Destination Name
                </label>
                <input
                  name="name"
                  disabled={!isEditing}
                  value={data.name || ""}
                  onChange={handleChange}
                  className="w-full p-2.5 border-b focus:border-blue-600 outline-none font-bold text-lg bg-transparent disabled:border-transparent"
                />
              </div>

              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
                  Category
                </label>
                <select
                  name="category"
                  disabled={!isEditing}
                  value={data.category || ""}
                  onChange={handleChange}
                  className="w-full p-2.5 border rounded-xl bg-white disabled:bg-gray-50 font-semibold"
                >
                  <option value="">Select Category</option>
                  {CATEGORY_OPTIONS.map((cat) => (
                    <option key={cat} value={cat}>
                      {cat}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
                  City
                </label>
                <input
                  name="city"
                  disabled={!isEditing}
                  value={data.city || "Jhansi"}
                  onChange={handleChange}
                  className="w-full p-2.5 border rounded-xl bg-white disabled:bg-gray-50 text-sm font-semibold"
                />
              </div>

              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
                  YouTube Video Link
                </label>
                <div className="flex items-center gap-2">
                  <input
                    name="ytVideoLink"
                    disabled={!isEditing}
                    value={data.ytVideoLink || ""}
                    onChange={handleChange}
                    placeholder="https://youtube.com/watch?v=..."
                    className="w-full p-2.5 border rounded-xl bg-white disabled:bg-gray-50 text-sm text-blue-600 font-medium"
                  />
                  {data.ytVideoLink && (
                    <a
                      href={data.ytVideoLink}
                      target="_blank"
                      rel="noreferrer"
                      className="p-2.5 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-100"
                    >
                      <ExternalLink size={16} />
                    </a>
                  )}
                </div>
              </div>
            </div>

            <div>
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
                Full Description
              </label>
              <textarea
                name="description"
                disabled={!isEditing}
                value={data.description || ""}
                onChange={handleChange}
                rows={4}
                className="w-full p-3 border rounded-xl bg-white disabled:bg-gray-50 text-sm text-gray-700 leading-relaxed resize-none"
              />
            </div>
          </div>

          {/* LOCATION & GEOLOCATION METADATA */}
          <div className="bg-white p-6 rounded-2xl border shadow-sm space-y-4">
            <h3 className="text-xs font-black text-blue-600 uppercase tracking-widest flex items-center gap-2">
              <Compass size={16} /> Location & GPS Mapping Data
            </h3>

            <div>
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
                Street Address / Landmark
              </label>
              <input
                name="address"
                disabled={!isEditing}
                value={data.location?.address || ""}
                onChange={handleLocationChange}
                className="w-full p-2.5 border rounded-xl bg-white disabled:bg-gray-50 text-sm font-semibold"
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
                  Latitude
                </label>
                <input
                  type="number"
                  step="any"
                  name="lat"
                  disabled={!isEditing}
                  value={data.location?.lat || 0}
                  onChange={handleLocationChange}
                  className="w-full p-2.5 border rounded-xl bg-white disabled:bg-gray-50 text-sm font-mono"
                />
              </div>

              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
                  Longitude
                </label>
                <input
                  type="number"
                  step="any"
                  name="lng"
                  disabled={!isEditing}
                  value={data.location?.lng || 0}
                  onChange={handleLocationChange}
