                  name="lat"
                  placeholder="25.4484"
                  onChange={handleChange}
                  className="w-full border p-2.5 rounded-xl text-sm font-mono outline-none focus:border-blue-500"
                />
              </div>

              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">
                  Longitude
                </label>
                <input
                  type="number"
                  step="any"
