            type="text"
            placeholder="Search restaurants by name..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-1/3 border p-2.5 rounded-xl text-sm outline-none focus:border-orange-500"
          />

          <div className="flex items-center gap-4">
